using System;using System.Collections;using System.Collections.Generic;using System.Data;using System.Data.Common;using System.IO;using System.Reflection;using System.Runtime.Serialization;using System.Threading.Tasks;using System.Windows.Forms;
class OrderLinkRegression{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static Assembly app;static Type repo,model;static string cust,marker;static int checks;static DateTime date=new DateTime(2099,1,2);
 static object Get(object o,string n){return o.GetType().GetProperty(n,F).GetValue(o,null);}static void Set(object o,string n,object v){o.GetType().GetProperty(n,F).SetValue(o,v,null);}static object Field(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}static void Put(object o,string n,object v){o.GetType().GetField(n,F).SetValue(o,v);}static object Call(object o,string n,params object[]a){try{return o.GetType().GetMethod(n,F).Invoke(o,a);}catch(TargetInvocationException e){throw e.InnerException;}}static object Static(string n,params object[]a){try{return repo.GetMethod(n,BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Invoke(null,a);}catch(TargetInvocationException e){throw e.InnerException;}}static void Check(bool b,string m){if(!b)throw new Exception(m);checks++;}
 static DbConnection Conn(){var c=(DbConnection)app.GetType("PineTree.Classes.DB").GetMethod("CreateConnection").Invoke(null,null);c.Open();return c;}
 static DataTable Sql(DbConnection c,DbTransaction t,string sql,params object[]pairs){using(var q=c.CreateCommand()){q.Transaction=t;q.CommandText=sql;for(int i=0;i<pairs.Length;i+=2){var p=q.CreateParameter();p.ParameterName=(string)pairs[i];p.Value=pairs[i+1]??DBNull.Value;q.Parameters.Add(p);}using(var r=q.ExecuteReader()){var rows=new DataTable();rows.Load(r);return rows;}}}
 static object NewOrder(long? link){var o=Activator.CreateInstance(model);Set(o,"LinkToOrderId",link);Set(o,"CustCode",cust);Set(o,"OrderDate",date);Set(o,"RequestedDueAt",date.AddDays(2));Set(o,"OrderChannel","소나무그래픽");Set(o,"DeliveryType","선불택배");Set(o,"DeliveryFee",7000m);Set(o,"OrderTitle",marker);Set(o,"OrderDescription","independent memo");Set(o,"ProductionStatus","신규");Set(o,"SourceChannel","LINK_TEST");Set(o,"Items",Activator.CreateInstance(typeof(List<>).MakeGenericType(app.GetType("PineTree.Classes.OrderItemSaveData"))));return o;}
 static DataRow Header(long id){return (DataRow)Static("GetOrderForEdit",id);}
 static void Ui(DataRow root){var type=app.GetType("PineTree.UserControls.UcOrderDesignPad");using(var pad=(UserControl)FormatterServices.GetUninitializedObject(type)){typeof(UserControl).GetConstructor(Type.EmptyTypes).Invoke(pad,new object[0]);Call(pad,"InitializeComponent");Call(pad,"InitOrderItemTable");Call(pad,"InitOrderEditor");Call(pad,"InitPreviewEvent");var mode=type.GetField("m_DialogMode",F);mode.SetValue(pad,Enum.Parse(mode.FieldType,"New"));Set(Field(pad,"tbRemark"),"Text","keep memo");Call(pad,"ApplyLinkedOrder",root);
 foreach(string n in new[]{"dtmOrder","dtmDelivery","tbCustName","tbCustCode","btnCustList","cbChannel","cbDeliveryType","tbDeliveryFee"})Check(!(bool)Get(Field(pad,n),"Enabled"),"Inherited field locked: "+n);Check((bool)Get(Field(pad,"tbRemark"),"Enabled")&&(string)Get(Field(pad,"tbRemark"),"Text")=="keep memo","Memo preserved and enabled");var save=Call(pad,"CreateOrderSaveData");Check((long?)Get(save,"LinkToOrderId")==Convert.ToInt64(root["OrderId"]),"Link root in save model");Check((string)Get(save,"CustCode")==cust && (decimal)Get(save,"DeliveryFee")==7000m,"Original header copied");root["RequestedDueAt"]=DBNull.Value;Call(pad,"ApplyLinkedOrder",root);Check(Get(Call(pad,"CreateOrderSaveData"),"RequestedDueAt")==null && Convert.ToString(Get(Field(pad,"dtmDelivery"),"Text"))=="","Missing original due date remains empty");Call(pad,"ResetNewOrder");Check(Get(Call(pad,"CreateOrderSaveData"),"LinkToOrderId")==null && (bool)Get(Field(pad,"tbCustName"),"Enabled"),"New order clears link and unlocks header");}
 var dt=app.GetType("PineTree.Dialogs.DialogOrderList");using(var dialog=(Form)Activator.CreateInstance(dt)){var candidates=(DataTable)Static("GetOrderLinkCandidates",date,"");Call(dialog,"BindOrders",candidates);var grid=Field(dialog,"FGrid1");Set(grid,"Row",1);Call(dialog,"SelectCurrentOrder");Check(Get(dialog,"SelectedOrderId")!=null && dialog.DialogResult==DialogResult.OK,"Order picker selects an order ID");}
 }
 [STAThread]static int Main(string[]args){long rootId=0;try{Application.EnableVisualStyles();app=Assembly.LoadFrom(Path.GetFullPath(args[0]));Assembly.LoadFrom(Path.GetFullPath(Path.Combine(Path.GetDirectoryName(args[0]),"..","..","dll","MySql.Data.dll")));repo=app.GetType("PineTree.Classes.OrderRepository");model=app.GetType("PineTree.Classes.OrderSaveData");marker="LINK_REGRESSION_"+Guid.NewGuid().ToString("N");using(var c=Conn())cust=Convert.ToString(Sql(c,null,"SELECT CustCode FROM Customers ORDER BY CustCode LIMIT 1").Rows[0][0]);rootId=(long)Static("UpsertOrder",NewOrder(null));string baseNo=Convert.ToString(Header(rootId)["OrderNo"]);
 using(var c=Conn())using(var t=c.BeginTransaction()){var child=NewOrder(rootId);long id=(long)Static("SaveOrderCore",c,t,child);Check(Convert.ToString(Sql(c,t,"SELECT OrderNo FROM OrderInfo WHERE OrderId=@Id","@Id",rootId).Rows[0][0])==baseNo+"_1","Root renamed inside transaction");t.Rollback();}Check(Convert.ToString(Header(rootId)["OrderNo"])==baseNo,"Rollback restores original root number");
 var wrong=NewOrder(rootId);Set(wrong,"DeliveryFee",1m);bool rejected=false;try{Static("UpsertOrder",wrong);}catch(InvalidOperationException){rejected=true;}Check(rejected && Convert.ToString(Header(rootId)["OrderNo"])==baseNo,"Stale or modified inherited header rejected atomically");
 Ui((DataRow)Static("GetOrderLinkSource",rootId));long second=(long)Static("UpsertOrder",NewOrder(rootId));Check(Convert.ToString(Header(rootId)["OrderNo"])==baseNo+"_1" && Convert.ToString(Header(second)["OrderNo"])==baseNo+"_2","First link creates _1 and _2");Check(Convert.ToInt64(Header(second)["OrderGroupId"])==rootId,"Root ID persisted");var source=(DataRow)Static("GetOrderLinkSource",second);Check(Convert.ToInt64(source["OrderId"])==rootId && Convert.ToString(source["NextOrderNo"])==baseNo+"_3","Selecting suffixed child resolves root and next number");
 long third=(long)Static("UpsertOrder",NewOrder(second));Check(Convert.ToString(Header(third)["OrderNo"])==baseNo+"_3","Link through child stays in same group");
 var tasks=new Task<long>[4];for(int i=0;i<tasks.Length;i++)tasks[i]=Task.Run(()=> (long)Static("UpsertOrder",NewOrder(second)));Task.WaitAll(tasks);var numbers=new HashSet<string>();foreach(var task in tasks)numbers.Add(Convert.ToString(Header(task.Result)["OrderNo"]));for(int i=4;i<=7;i++)Check(numbers.Contains(baseNo+"_"+i),"Concurrent sequence "+i);Check(numbers.Count==4,"Concurrent numbers unique");
 using(var c=Conn())using(var t=c.BeginTransaction()){long id=(long)Static("SaveOrderCore",c,t,NewOrder(null));string next=Convert.ToString(Sql(c,t,"SELECT OrderNo FROM OrderInfo WHERE OrderId=@Id","@Id",id).Rows[0][0]);Check(next!=baseNo && !next.Contains("_"),"Normal numbering does not reuse linked base");t.Rollback();}
 var edit=NewOrder(null);Set(edit,"OrderId",second);Set(edit,"CustCode","tampered");Set(edit,"OrderDate",date.AddDays(10));Set(edit,"DeliveryFee",0m);Static("UpsertOrder",edit);var restored=Header(second);Check(Convert.ToString(restored["CustCode"])==cust && Convert.ToDecimal(restored["DeliveryFee"])==7000m && Convert.ToDateTime(restored["OrderDate"])==date,"Existing linked header remains inherited during edits");Check(Convert.ToString(restored["OrderDescription"])=="independent memo","Memo remains editable");Console.WriteLine("PASS: "+checks+" linked-order UI, transaction, numbering and concurrency checks");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{if(rootId>0){using(var c=Conn()){Sql(c,null,"DELETE FROM OrderInfo WHERE OrderGroupId=@Root AND SourceChannel='LINK_TEST' AND OrderTitle=@Marker","@Root",rootId,"@Marker",marker);Sql(c,null,"DELETE FROM OrderInfo WHERE OrderId=@Root AND SourceChannel='LINK_TEST' AND OrderTitle=@Marker","@Root",rootId,"@Marker",marker);Console.WriteLine("Cleaned temporary linked-order fixtures");}}}}
}
